const KEY_LENGTHS: { [name: string]: number } = {
  "aes-128-cbc": 16,
  "aes-192-cbc": 24,
  "aes-256-cbc": 32,
  "aes-128-ctr": 16,
  "aes-192-ctr": 24,
  "aes-256-ctr": 32,
  "aes-128-gcm": 16,
  "aes-192-gcm": 24,
  "aes-256-gcm": 32,
  "chacha20-poly1305": 32,
};

function pattern(length: number, seed: number): Buffer {
  const out = Buffer.alloc(length);
  for (let i = 0; i < length; i++) out[i] = (i * 31 + seed * 7 + 3) & 0xff;
  return out;
}

let failures = 0;
for (const [name, length, expectedHex, expectedTag] of VECTORS) {
  const key = pattern(KEY_LENGTHS[name]!, length + 1);
  const iv = pattern(name.endsWith("cbc") || name.endsWith("ctr") ? 16 : 12, length + 2);
  const plaintext = pattern(length, length + 3);
  const aead = expectedTag !== "";
  const cipher = createCipheriv(name, key, iv);
  if (aead) (cipher as CipherGCM).setAAD(pattern(length % 7, 5));
  const ciphertext = Buffer.concat([cipher.update(plaintext), cipher.final()]);
  const tag = aead ? (cipher as CipherGCM).getAuthTag().toString("hex") : "";
  const decipher = createDecipheriv(name, key, iv);
  if (aead) {
    const aeadDecipher = decipher as DecipherGCM;
    aeadDecipher.setAAD(pattern(length % 7, 5));
    aeadDecipher.setAuthTag(Buffer.from(tag, "hex"));
  }
  const roundTrip = Buffer.concat([decipher.update(ciphertext), decipher.final()]);
  const ok = ciphertext.toString("hex") === expectedHex && tag === expectedTag && roundTrip.equals(plaintext);
  if (!ok) failures++;
  console.log(name, length, ciphertext.length, ok ? "match" : `mismatch ${ciphertext.toString("hex")} ${tag}`);
}
console.log("failures", failures);
